export{readingExamples}from './reading-check-core.js';
import{READING_CHECK_LETTERS,READING_REASONS,readingLetter,readingExamples,normalizeReadingCheck,normalizeReadingReview}from './reading-check-core.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function readingCheckMarkup(check,review=null){if(!check)return'';const letter=readingLetter(check.letterId);return'<section class="reading-check"><span class="reading-check-label">ПОСЛЕ БУКВЫ '+esc(letter?.[2]||'')+'</span><h3>Проверка чтения</h3><p>'+check.count+' сочетаний. Прочитайте по порядку и прикрепите одну голосовую запись. Выполните до следующего занятия.</p><ol class="reading-check-prompts">'+check.prompts.map((text,index)=>'<li><span class="reading-check-number">'+(index+1)+'</span><span class="reading-check-ar" lang="ar" dir="rtl">'+esc(text)+'</span></li>').join('')+'</ol>'+(review?'<div class="reading-check-score"><strong>Верно: '+review.correctCount+' из '+review.count+' · Ошибок: '+review.mistakeCount+'</strong>'+(review.difficulties.length?'<p>Повторите отмеченные сочетания:</p><ul>'+review.difficulties.map(item=>'<li><span class="reading-check-ar" lang="ar" dir="rtl">'+esc(item.prompt)+'</span><span>'+esc(READING_REASONS[item.reason]||'Повторить')+'</span></li>').join('')+'</ul>':'<p>Все сочетания отмечены преподавателем как верные.</p>')+'</div>':'<p class="reading-check-note">Произношение проверит преподаватель. Автоматической оценки голоса нет.</p>')+'</section>';}
export function mountReadingCheckEditor(root,{initial=null,onChange=()=>{}}={}){
 let enabled=Boolean(initial),current=initial||{letterId:'mim',count:10,prompts:readingExamples('mim',10)};root.innerHTML='<section class="reading-check-editor"><label class="reading-check-toggle"><input type="checkbox" data-enable-reading '+(enabled?'checked':'')+'>Добавить проверку после пройденной буквы</label><p class="reading-check-note">Преподаватель решает, нужна ли проверка. Укажите изученную букву и оставьте сочетания только из уже пройденных букв.</p><div data-reading-options></div></section>';const toggle=root.querySelector('input'),options=root.querySelector('[data-reading-options]');
 function draw(){options.replaceChildren();if(!enabled)return;options.innerHTML='<div class="reading-check-fields"><label>Пройденная буква<select data-letter aria-label="Пройденная буква">'+READING_CHECK_LETTERS.map(([id,char,name])=>'<option value="'+id+'"'+(id===current.letterId?' selected':'')+'>'+esc(char+' · '+name)+'</option>').join('')+'</select></label><label>Количество<select data-count aria-label="Количество сочетаний"><option value="10"'+(current.count===10?' selected':'')+'>10 сочетаний</option><option value="15"'+(current.count===15?' selected':'')+'>15 сочетаний</option></select></label></div><p class="reading-check-note">Это ДЗ до следующего занятия. Примеры можно отредактировать.</p><div data-prompts class="reading-check-inputs"></div>';const rows=options.querySelector('[data-prompts]');current.prompts.forEach((value,i)=>{const label=root.ownerDocument.createElement('label');label.innerHTML='<span>Сочетание '+(i+1)+'</span><input type="text" class="reading-check-ar" lang="ar" dir="rtl" maxlength="24" value="'+esc(value)+'">';label.querySelector('input').oninput=event=>{current.prompts[i]=event.target.value;onChange();};rows.append(label);});options.querySelector('[data-letter]').onchange=event=>{current={letterId:event.target.value,count:current.count,prompts:readingExamples(event.target.value,current.count)};draw();onChange();};options.querySelector('[data-count]').onchange=event=>{const count=Number(event.target.value),examples=readingExamples(current.letterId,count);current={...current,count,prompts:Array.from({length:count},(_,i)=>current.prompts[i]||examples[i])};draw();onChange();};}
 toggle.onchange=()=>{enabled=toggle.checked;draw();onChange();};draw();return{value:()=>enabled?normalizeReadingCheck(current):null,disable:()=>{enabled=false;toggle.checked=false;draw();onChange();},dispose:()=>root.replaceChildren()};
}
export function mountReadingReview(root,{check,initial=null}={}){
 if(!check)return{value:()=>null,dispose:()=>{}};const marks=Array.from({length:check.count},(_,i)=>initial?.marks?.[i]||null);root.innerHTML='<section class="reading-review"><h4>Чтение после буквы '+esc(readingLetter(check.letterId)?.[2]||'')+'</h4><p>Прослушайте запись и отметьте каждое сочетание. Результат увидит ученик.</p><button type="button" class="lesson-text-button" data-all-correct>Все сочетания прочитаны верно</button><ol class="reading-review-items">'+check.prompts.map((text,index)=>'<li data-index="'+index+'"><div><span class="reading-check-number">'+(index+1)+'</span><span class="reading-check-ar" lang="ar" dir="rtl">'+esc(text)+'</span></div><label>Результат<select data-mark aria-label="Результат сочетания '+(index+1)+'"><option value="">Выберите</option><option value="correct">Верно</option><option value="error">Нужно повторить</option></select></label><label data-reason-label hidden>Сложность<select data-reason>'+Object.entries(READING_REASONS).map(([key,label])=>'<option value="'+key+'">'+esc(label)+'</option>').join('')+'</select></label></li>').join('')+'</ol><p data-score role="status">Пока не проверено.</p></section>';
 const score=root.querySelector('[data-score]');function update(){root.querySelectorAll('[data-index]').forEach(item=>{const i=Number(item.dataset.index),mark=marks[i];item.querySelector('[data-mark]').value=mark?(mark.correct?'correct':'error'):'';item.querySelector('[data-reason-label]').hidden=!mark||mark.correct;if(mark?.reason)item.querySelector('[data-reason]').value=mark.reason;});const checked=marks.filter(Boolean),errors=checked.filter(mark=>!mark.correct).length;score.textContent='Проверено: '+checked.length+' из '+check.count+(checked.length?' · Ошибок: '+errors:'');}
 root.querySelectorAll('[data-index]').forEach(item=>{const index=Number(item.dataset.index);item.querySelector('[data-mark]').onchange=event=>{marks[index]=event.target.value?{correct:event.target.value==='correct',reason:event.target.value==='correct'?null:item.querySelector('[data-reason]').value}:null;update();};item.querySelector('[data-reason]').onchange=event=>{if(marks[index]&&!marks[index].correct)marks[index].reason=event.target.value;};});root.querySelector('[data-all-correct]').onclick=()=>{marks.fill(null);for(let i=0;i<marks.length;i++)marks[i]={correct:true,reason:null};update();};update();return{value:()=>normalizeReadingReview(marks,check),dispose:()=>root.replaceChildren()};
}
